-- 1. Unified Site Content Document
INSERT INTO public.site_content (id, data, updated_at)
VALUES (1, '{"theme": {"white": "#fffeee", "black": "#000000", "grey": "#595959", "lineD": "rgba(255,254,238,.16)", "lineL": "rgba(0,0,0,.16)", "font": "''Special Elite'',''Courier New'',Courier,monospace", "fontFace": "", "s0": "clamp(8px,.72vw,10px)", "s1": "clamp(11.5px,1.02vw,14.5px)", "s2": "clamp(12.5px,1.22vw,16.5px)", "s3": "clamp(14.5px,1.62vw,21px)", "s4": "clamp(22px,4.2vw,55px)", "s5": "clamp(20px,2.5vw,35px)", "sec": "80vh", "ease": "cubic-bezier(.16,1,.3,1)", "slideMs": 11000}, "assets": {"heroLogo": "img/wordmark-white.png", "intro": "assets/video/intro.mp4", "workBand": "assets/video/work-bts.mp4", "workBandPoster": "assets/video/poster-work-bts.jpg", "contactBand": "assets/video/web-maya-ma.mp4", "contactBandPoster": "assets/video/poster-maya-ma.jpg"}, "pages": {"team": {"eyebrow": "Team Chinoé", "title": "Love, Passion & Film", "lead": "Team Chinoé is the full creative and operational engine behind Chinoétales, direction, cinematography, production design, art direction, editing, styling, and the operations that hold it all together. Meet the people behind the work."}, "work": {"eyebrow": "Chinoétales Productions", "title": "Catalogue of Work", "lead": "A working reference of our released music-video output, titles, in-house director credits, and the artists we''ve built with."}, "contact": {"eyebrow": "Work With Us", "title": "Let''s Talk.", "lead": "Have a project? Want to collaborate, commission a film, or need creative consultation? Every conversation begins here."}}, "settings": {"statVideos": "100+", "statYears": "2021–26", "statArtists": "50+", "statDirectors": "20+", "contactEmail1": "chinoetales@gmail.com", "phones": ["+977 9700043499", "+977 9700043489", "+977 9700043479"], "location": "Based in Kathmandu, Nepal\nAvailable for projects globally", "playlist": "https://www.youtube.com/watch?v=DZ4BtMpaJaU&list=PL9Z9We-FA4DdMxamqRL4m3N7bARTvdkwo", "social": [{"n": "YouTube", "u": "https://www.youtube.com/@chinoetalesofficial"}, {"n": "Instagram", "u": "https://www.instagram.com/chinoetales.productions/"}, {"n": "Facebook", "u": "https://www.facebook.com/chinoetales.productions"}, {"n": "LinkedIn", "u": "https://www.linkedin.com/company/chino%C3%A9tales-productions/"}, {"n": "TikTok", "u": "https://www.tiktok.com/@chinoetalesofficial"}, {"n": "Pinterest", "u": "https://www.pinterest.com/chinoetalesofficial/"}, {"n": "Giphy", "u": "https://giphy.com/channel/chinoetalesofficial"}], "copyright": "© 2026 Chinoétales Films Pvt. Ltd."}, "directors": [{"a": "Abhi Sampang Rai", "role": "CEO / Director", "style": "Cinematic Storytelling", "about": "Leads Chinoétales as both a company and a creative force, setting the studio''s vision while staying hands-on in the director''s chair. His signature combines bold visual aesthetics with deeply emotional storytelling, translating lyrical content into powerful visual metaphors.", "works": ["<b>Sparsha Sangeet</b> · Purna Rai & Dajubhaiharu", "<b>Ma Mare Pani</b> · Swar", "<b>Soltini</b> · Ekdev Limbu", "<b>Nindra Ma</b> · The Solace", "<b>Maya Ko Aago</b> · Rockheads"], "q": "\"I believe every song carries a visual story waiting to be discovered. Our job is not to create new stories, but to excavate the emotional truth already embedded in the music.\"", "photo": "assets/img/team/abhi.jpg"}, {"a": "Bikesh Magar", "role": "CTO / DOP", "style": "Light & Composition", "about": "The technical backbone of Chinoétales'' image-making, leading the camera department while shaping the studio''s broader technical direction and equipment strategy. A cinematographer with a sharp eye for light and composition.", "works": ["<b>Ma Mare Pani</b> · Swar", "<b>Like Jennie</b> · Cover Project", "Lead DOP across commercials & music videos"], "q": "\"Technical excellence is the foundation upon which artistic vision stands. Every decision, from camera movement to colour temperature, serves the story.\"", "photo": "assets/img/team/bikesh.jpg"}, {"a": "Shristi Rai", "role": "CFO / Production Designer", "style": "World-Building", "about": "Holds the financial backbone of Chinoétales together while shaping the visual world of every set she designs, blending a producer''s discipline with a designer''s eye for emotional authenticity and cultural sensitivity.", "works": ["<b>Jhim Jhimaune Aankha</b> · Ekdev Limbu", "<b>Hey Sailaa</b> · Abhaya & The Steam Engines", "Production design across flagship projects"], "q": "\"The most powerful stories are the ones that feel inevitable, where every visual choice seems like the only possible choice. That''s when art happens.\"", "photo": "assets/img/team/shristi.jpg"}, {"a": "Aadi Pahari", "role": "Operational Manager", "style": "Flawless Execution", "about": "Keeps Chinoétales running, the person who turns a creative brief into a schedule, a schedule into a shoot day, and a shoot day into a delivered project. Ground-level experience across productions of every scale means nothing falls through the cracks.", "works": [], "q": "\"Great productions aren''t built on great ideas alone, they''re built on flawless execution. My role is making sure the team can focus on the work, not the logistics.\"", "photo": "assets/img/team/aadi.jpg"}, {"a": "Santosh S. Thakuri", "role": "Creative Head", "style": "Contemporary Energy", "about": "Brings fresh, contemporary energy to Chinoétales'' creative direction, shaping the studio''s evolving visual language, pushing projects toward dynamic, digital-age storytelling while staying rooted in cultural authenticity.", "works": ["Contemporary music video & commercial projects", "Ongoing creative direction across the pipeline"], "q": "\"Every generation has its own visual language. My goal is to help our stories find expressions that feel true to this moment, honest, dynamic, and authentic.\"", "photo": "assets/img/team/santosh.jpg"}, {"a": "Devarshi.S", "role": "Creative Director", "style": "Visual Precision", "about": "Shapes the creative backbone of every production, translating raw concepts into a coherent visual and narrative direction, with meticulous composition, complex technical problem-solving, and an unwavering commitment to artistic integrity.", "works": ["<b>Ma Mare Pani</b> · Swar", "<b>Makhamali</b> · The Hulaki", "<b>Mandainani Mana</b> · Ekdev Limbu"], "q": "\"Technology should become invisible so the story can become everything. That''s the standard every creative decision has to meet.\"", "photo": "assets/img/team/devarshi.jpg"}, {"a": "Kiwa Khimdung Rai", "role": "Cinematographer", "style": "Motion & Frame", "about": "Brings a sharp visual instinct to every frame he shoots, serving the story through light, movement, and composition rather than spectacle for its own sake, across music videos, commercials, and documentary-style projects.", "works": [], "q": "\"A shot only works if it disappears into the story. My job is to make every frame feel like it couldn''t have been captured any other way.\"", "photo": "assets/img/team/kiwa.jpg"}, {"a": "Samasti Rai", "role": "Art Director", "style": "Production Design", "about": "Builds the visual world every Chinoétales project lives in, from set dressing to props to the overall aesthetic language of a production. Art direction is never an afterthought; it''s baked into the story from day one.", "works": ["<b>Jhim Jhimaune Aankha</b> · Ekdev Limbu", "Art direction across music video & commercial projects"], "q": "\"Great production design should never call attention to itself, it should just feel like the only world this story could exist in.\"", "photo": "assets/img/team/samasti.jpg"}, {"a": "Ongdi Moktan", "role": "Art Director", "style": "Detail & Craft", "about": "Supports the art department across every stage of production, from prep and sourcing through on-set execution. An eye for detail that keeps the art department running smoothly under pressure.", "works": [], "q": "\"The details nobody notices are usually the ones holding the whole shot together.\"", "photo": "assets/img/team/ongdi.jpg"}, {"a": "Dipika Rai", "role": "Content Manager", "style": "Story & Reach", "about": "Manages how Chinoétales'' work reaches the world, coordinating content across platforms, timelines, and campaigns, from behind-the-scenes documentation to full release strategy for finished projects.", "works": [], "q": "\"A great film still needs the right story told about how it reaches people. That''s the part of the job I care about most.\"", "photo": "assets/img/team/dipika.jpg"}, {"a": "Arbind", "role": "DIT", "style": "Data Integrity", "about": "Responsible for the integrity of Chinoétales'' footage from the moment it''s captured to the moment it reaches the edit suite, data management, on-set backups, and first-pass technical quality checks.", "works": [], "q": "\"Nobody notices the DIT until something goes wrong. My job is making sure that never happens.\"", "photo": "assets/img/team/arbind.jpg"}, {"a": "Nichal Gurung", "role": "Editor", "style": "Rhythm & Pacing", "about": "Shapes the final rhythm of Chinoétales'' projects in the edit suite. With an innate sense of pacing and music-visual synchronisation, his editing is where performance, cinematography, and story finally come together.", "works": [], "q": "\"Editing is where the story is truly told. When the cuts disappear, that''s when the audience stops watching and starts feeling.\"", "photo": "assets/img/team/nischal.jpg"}, {"a": "Bomi Rai", "role": "Stylist", "style": "Character & Look", "about": "Shapes how every artist and cast member looks on screen, wardrobe, styling, and the visual identity that has to hold up under studio lights and outdoor locations alike, always built for both camera and story.", "works": [], "q": "\"Styling isn''t decoration, it''s characterisation. What someone wears has to tell you who they are before they say a single word.\"", "photo": "assets/img/team/bomi.jpg"}], "works": [{"t": "Maya Ma", "a": "Purna Rai & Dajubhaiharu", "d": "Abhi Sampang Rai", "y": "2025", "id": "5yuuRveinFc", "cat": "Music Video", "keyart": "assets/img/posters/maya-ma.jpg", "story": "\"In love\" — Purna Rai''s unmistakable voice carrying a song about being fully, helplessly inside a feeling, with visuals to match its warmth.", "notes": ["Shristi Rai''s first executive-producer credit; Bikesh Magar covered camera, edit, VFX, and color across the entire post pipeline."], "seo": "Purna Rai Maya Ma music video, Maya Ma official video, Purna Rai new song"}, {"t": "Laijau Malai", "a": "Tribal Rain", "d": "Abhi Sampang Rai", "y": "2025", "id": "ntKzGQEDBXs", "cat": "Music Video", "dop": "Bikesh Magar", "e": "Bikesh Magar", "col": "Bikesh Magar", "credits": [{"r": "Art Direction", "n": "Shristi Rai"}, {"r": "Assistant Director", "n": "Saman Maharjan"}, {"r": "Make-Up & Stylist", "n": "Bomi Rai"}, {"r": "DIT", "n": "Purushottam Kandel"}, {"r": "Behind Credits", "n": "Santosh S. Thakuri"}], "story": "\"Take me away\" — a yearning to be carried somewhere else entirely, given weight by Tribal Rain''s beloved catalogue and released on Valentine''s Day.", "notes": ["A high-anticipation release for one of Nepal''s most cherished bands, premiered on Feb 14 with a full BTS companion film shot by Santosh Shah Thakuri."], "seo": "Tribal Rain Laijau Malai music video, Laijau Malai official video, Tribal Rain new song 2025"}, {"t": "Ma Mare Pani", "a": "Swar", "d": "Abhi Sampang Rai", "y": "2025", "id": "lsqbpw67hSs", "cat": "Music Video", "keyart": "assets/img/posters/ma-mare-pani.jpg", "story": "\"Even if I die\" — devotion pushed to its absolute limit, a love professed beyond the boundary of life itself.", "notes": ["A full-department production with Santosh Shah Thakuri managing post — the workflow template the studio now uses on most flagship videos."], "seo": "Swar Ma Marey Pani music video, Ma Marey Pani official video"}, {"t": "Sparsha Sangeet", "a": "Purna Rai & Dajubhaiharu", "d": "Abhi Sampang Rai", "y": "2024", "id": "K-w04FG6eyI", "cat": "Music Video", "dop": "Bikesh Magar", "pd": "Shristi Rai", "credits": [{"r": "Assistant Director", "n": "Saman Maharjan"}, {"r": "Cinematographer", "n": "Kiwa Khimdung Rai"}, {"r": "Art Direction", "n": "Shristi Rai"}, {"r": "Stylist", "n": "Shristi Rai"}, {"r": "Make-Up", "n": "Samasti Rai"}, {"r": "DIT", "n": "Purushottam Kandel"}], "keyart": "assets/img/posters/sparsha-sangeet.jpg", "e": "Robin Shrestha & Bikesh Magar & Ayush Suwal", "col": "Bikesh Magar", "story": "\"The music of touch\" — a tactile, sensory love song rendered as a series of moments where sound and touch blur into one feeling.", "notes": ["One of the studio''s largest crews to date — a three-editor post team and production support from Kaagaz Productions, whose members (Arshu Shrestha, Ongdi Moktan, Rushal Shrestha) later became ChinoeTales regulars."], "seo": "Purna Rai Sparsha Sangeet music video, Sparsha Sangeet official video, Purna Rai Dajubhaiharu"}, {"t": "Soltini", "a": "Ekdev Limbu", "d": "Abhi Sampang Rai", "y": "2024", "id": "HU5oZNvLmw8", "cat": "Music Video", "e": "Bikesh Magar", "col": "Bikesh Magar", "credits": [{"r": "Cinematographer", "n": "Bikesh Magar & Kiwa Khimdung Rai"}, {"r": "Stylist", "n": "Shristi Rai"}, {"r": "Make-Up", "n": "Samasti Rai"}, {"r": "Art Direction", "n": "Samasti Rai & Shristi Rai"}, {"r": "Associate Cinematographer", "n": "Purushottam Kandel"}, {"r": "DIT", "n": "Purushottam Kandel"}, {"r": "Associate Editor", "n": "Sobit Magar"}], "story": "\"Soltini\" — a playful, flirtatious courtship rooted in eastern-Nepal solti/soltini banter, full of teasing back-and-forth energy.", "notes": ["Kiwa Khimdung''s first cinematography credit with the studio, joining a full art and styling department led by the Rai sisters."], "seo": "Ekdev Limbu Soltini music video, Soltini official video, solti soltini song"}, {"t": "K Garu", "a": "John Rai & The Locals", "d": "Abhi Sampang Rai", "y": "2024", "id": "fGF10RLUm1U", "cat": "Music Video", "dop": "Bikesh Magar", "e": "Bikesh Magar", "col": "Bikesh Magar", "credits": [{"r": "Co-Director", "n": "Abhi Sampang Rai"}, {"r": "Cast", "n": "Samasti Rai & Uttam Rai"}, {"r": "Assistant Director", "n": "Saman Maharjan"}, {"r": "Art Direction", "n": "Shristi Rai"}, {"r": "Project Manager", "n": "Shristi Rai"}, {"r": "Assistant Cinematographer", "n": "Kiwa Khimdung Rai"}, {"r": "DIT", "n": "Purushottam Kandel"}, {"r": "Post Production", "n": "Chinoe VFX"}, {"r": "Stylist", "n": "Samasti Rai"}, {"r": "Fashion Designer", "n": "Samasti Rai"}, {"r": "Make-Up", "n": "Samasti Rai"}], "story": "\"What do I do?\" — the helpless spiral of loving someone you can''t reach, played out by returning on-screen pair Samasti Rai and Uttam Rai.", "notes": ["First project credited to the in-house post unit \"Chinoe VFX\" — the studio formalizing its post-production arm."], "seo": "John Rai K Garu music video, K Garu official video, John Rai and The Locals"}, {"t": "Nindra Ma", "a": "The Solace", "d": "Abhi Sampang Rai", "y": "2024", "id": "zWVERn9EfWE", "cat": "Music Video", "story": "\"In sleep\" — a dreamscape video where the line between what''s dreamed and what''s remembered keeps dissolving.", "notes": ["A dream-logic concept supported by Saurav Shakya''s VFX; guest editor Amin Rai cut the project."], "seo": "The Solace Nindra Ma music video, Nindra Ma official video"}, {"t": "Jhim Jhimaune Aankha", "a": "Ekdev Limbu", "d": "Shristi Rai & Samasti Rai", "y": "2024", "id": "DZ4BtMpaJaU", "cat": "Music Video", "keyart": "assets/img/posters/jhim-jhimaune-aankha.jpg", "story": "\"Twinkling eyes\" — falling for someone one blink at a time; a soft-focus romance built on close-ups and light.", "notes": ["The Rai sisters'' first co-directed project — directing and art-directing simultaneously, a double role unique to this release."], "seo": "Ekdev Limbu Jhim Jhimaune Aankha music video, Jhim Jhimaune Aankha official video"}, {"t": "Hey Sailaa", "a": "Abhaya & The Steam Engines", "d": "Abhi Sampang Rai", "y": "2025", "id": "83B-_ibtvYU", "cat": "Music Video", "dop": "Bikesh Magar", "e": "Abhi Sampang Rai & Bikesh Magar", "col": "Devarshi.S", "credits": [{"r": "Co-Director", "n": "Shristi Rai"}, {"r": "Creative Director", "n": "Devarshi.S"}, {"r": "Cinematographer", "n": "Kiwa Khimdung Rai"}, {"r": "Art Direction", "n": "Samasti Rai & Ongdi Moktan"}, {"r": "Make-Up", "n": "Bomi Rai & Samasti Rai"}, {"r": "Stylist", "n": "Bomi Rai"}, {"r": "Project Manager", "n": "Aadi Pahari"}, {"r": "Associate Manager", "n": "Santosh S. Thakuri"}], "story": "\"Hey Saila\" — a folk-rock romp with one of Nepal''s most storied live bands, built around the teasing call-out of the title.", "notes": ["A twelve-credit crew for veteran act Abhaya & The Steam Engines — among the studio''s fullest productions of 2025."], "seo": "Abhaya and The Steam Engines Hey Saila music video, Hey Saila official video"}, {"t": "Bhagyamaani", "a": "The Hulaki", "d": "Arshu Shrestha", "y": "2025", "id": "zsTjVCaOWw8", "cat": "Music Video", "keyart": "assets/img/posters/bhagyamaani.jpg", "story": "\"Fortunate\" — counting the luck of ordinary blessings; a gratitude song shot with warmth rather than gloss.", "notes": ["Arshu Shrestha''s second directing credit, this time with Bikesh Magar on camera and Santosh Shah Thakuri supervising production."], "seo": "The Hulaki Bhagyamaani music video, Bhagyamaani official video"}, {"t": "Saathma", "a": "Nineties", "d": "Bikesh Magar", "y": "2024", "id": "uuDfIOf1XOE", "cat": "Music Video", "dop": "Bikesh Magar", "credits": [{"r": "Co-Director", "n": "Santosh S. Thakuri"}, {"r": "Creative Director", "n": "Santosh S. Thakuri"}], "story": "\"By my side\" — a song about the people who stay, shot as an understated portrait of companionship.", "notes": ["Bikesh Magar''s directorial debut for the studio, co-directed with Santosh Shah Thakuri in his first creative lead credit."], "seo": "Nineties Saathma music video, Saathma official video, Nineties Nepali band"}, {"t": "Fasaideu", "a": "Vek", "d": "Bikesh Magar", "y": "2026", "id": "Mh6AZNA6UzE", "cat": "Music Video", "keyart": "assets/img/posters/fasaideu.jpg", "story": "\"Entangle me\" — a flirtatious dare of a song; the video leans into playful tension and push-pull chemistry.", "notes": ["Bikesh Magar directing and shooting simultaneously, co-directed with Santosh Shah Thakuri — the same pairing as \"Saathma\", now with a fuller crew."], "seo": "Vek Fasaideu music video, Fasaideu official video, Vek new song"}, {"t": "Yei Maya Ho", "a": "Vek", "d": "Bikesh Magar", "y": "2026", "id": "eV3V2JHr9sU", "cat": "Music Video", "dop": "Bikesh Magar", "e": "Bikesh Magar", "col": "Bikesh Magar", "credits": [{"r": "Assistant Director", "n": "Santosh S. Thakuri"}, {"r": "Art Direction", "n": "Ongdi Moktan"}, {"r": "Stylist", "n": "Bomi Rai"}, {"r": "Make-Up", "n": "Bomi Rai"}, {"r": "DIT", "n": "Sobit Magar"}, {"r": "Project Coordinator", "n": "Aadi Pahari"}], "story": "\"This is love\" — the moment of naming the feeling out loud; Vek''s second ChinoeTales video answers the flirtation of \"Fasaideu\" with certainty.", "notes": ["The Bikesh Magar / Santosh Shah Thakuri directing team''s third outing together, and their second with Vek."], "seo": "Vek Yei Maya Ho music video, Yei Maya Ho official video"}, {"t": "Makhamali", "a": "The Hulaki", "d": "Devarshi.S", "y": "2026", "id": "tVs5gi5vw6w", "cat": "Music Video", "keyart": "assets/img/posters/makhamali.jpg", "p": "Abhi Sampang Rai", "e": "Bikesh Magar & Devarshi.S", "col": "Bikesh Magar & Devarshi.S", "credits": [{"r": "Art Direction", "n": "Ongdi Moktan"}, {"r": "Project Manager", "n": "Aadi Pahari"}, {"r": "Content Manager", "n": "Santosh S. Thakuri"}], "dop": "Bikesh Magar", "story": "\"Makhamali\" — named for the velvet marigold of Tihar garlands, a song about a love woven to last beyond seasons.", "notes": ["The Hulaki''s second ChinoeTales video, moving from Arshu Shrestha (\"Bhagyamaani\") to Devarshi Sharma behind the camera."], "seo": "The Hulaki Makhamali music video, Makhamali official video, makhamali song"}, {"t": "Mandainani Mana", "a": "Ekdev Limbu", "d": "Devarshi.S", "y": "2025", "id": "4ESj3_wpibA", "cat": "Music Video", "dop": "Bikesh Magar", "col": "Bikesh Magar & Devarshi.S", "credits": [{"r": "Creative Director", "n": "Abhi Sampang Rai"}, {"r": "Chief Assistant Director", "n": "Ongdi Moktan"}, {"r": "VFX", "n": "Bikesh Magar"}], "story": "\"The heart won''t listen\" — reason says move on, the heart refuses; a tug-of-war rendered in visual contrasts.", "notes": ["Back-to-back Ekdev Limbu releases two weeks apart, with Devarshi Sharma directing and co-coloring this one himself."], "seo": "Ekdev Limbu Mandainani Mana music video, Mandainani Mana official video"}, {"t": "Maila Dai", "a": "Abhijeet Khadgi", "d": "Devarshi.S", "y": "2024", "id": "bqqtnsW-zXk", "cat": "Music Video", "dop": "Bikesh Magar", "credits": [{"r": "Creative Director", "n": "Abhi Sampang Rai"}, {"r": "Cinematographer", "n": "Kiwa Khimdung Rai"}, {"r": "VFX", "n": "Saurav Shakya"}, {"r": "Art Direction", "n": "Shristi Rai"}, {"r": "DIT", "n": "Purushottam Kandel"}, {"r": "Assistant Director", "n": "Aakash Poudel"}, {"r": "Production Manager", "n": "Rushal Shrestha"}], "story": "\"Maila Dai\" — a character portrait of the middle brother, the one who carries the household quietly while nobody''s watching.", "notes": ["Devarshi Sharma''s first solo directing credit for the studio, backed by a full nine-person crew including VFX by Saurav Shakya."], "seo": "Abhijeet Khadgi Maila Dai music video, Maila Dai official video"}, {"t": "Sisir", "a": "Dibya Distry", "d": "Devarshi.S", "y": "2026", "id": "dIrLADwvj4A", "cat": "Music Video", "keyart": "assets/img/posters/sisir.jpg", "p": "Abhi Sampang Rai", "e": "Devarshi.S & Bikesh Magar", "col": "Devarshi.S & Bikesh Magar", "credits": [{"r": "Assistant Director", "n": "Ongdi Moktan"}, {"r": "Make-Up", "n": "Samasti Rai"}, {"r": "Project Manager", "n": "Aadi Pahari"}, {"r": "Graphics", "n": "Santosh S. Thakuri"}], "story": "\"Winter\" — the season as a state of the heart; frost, breath, and the slow wait for a thaw.", "notes": ["Devarshi Sharma directing and co-editing/coloring his own cut, with Santosh Shah Thakuri on graphics."], "seo": "Dibya Distry Sisir music video, Sisir official video"}, {"t": "Alvida", "a": "Mohini", "d": "Devarshi.S", "y": "2025", "id": "NTKAr2fsO4w", "cat": "Music Video", "keyart": "assets/img/posters/alvida.jpg", "story": "\"Farewell\" — a goodbye told in stages: the packing, the last look back, the door closing, the after.", "notes": ["Kiwa Khimdung''s first lead-DOP credit, with Devarshi Sharma directing and co-editing his own cut."], "seo": "Mohini Alvida music video, Alvida official video, Nepali farewell song"}, {"t": "Ajambari Jhari", "a": "Suvam Gurung", "d": "Aakash Poudel", "y": "2025", "id": "HTYT_6jygJc", "cat": "Music Video", "story": "\"Everlasting rain\" — love as weather that never lets up, shot in a rain-soaked palette of greys and warm interiors.", "notes": ["The studio''s first release with a companion BTS film — the start of the behind-the-scenes series that now accompanies most premieres."], "seo": "Suvam Gurung Ajambari Jhari music video, Ajambari Jhari official video, Ajambari Jhari BTS"}, {"t": "Kura", "a": "Freebirds", "d": "Aakash Poudel", "y": "2026", "id": "o_vFurJR31E", "cat": "Music Video", "keyart": "assets/img/posters/kura.jpg", "story": "\"Talk\" — the conversations we rehearse and never have; Freebirds return to the studio after \"Parichaya\".", "notes": ["_[Crew details not on file — confirm credits before publishing.]_ Directed by Aakash per the tracker; BTS film released May 13."], "seo": "Freebirds Kura music video, Kura official video"}, {"t": "Maya Ko Sansaar", "a": "Deeya Gurung", "d": "Aakash Poudel", "y": "2025", "id": "fi_rRrrQWGQ", "cat": "Music Video", "keyart": "assets/img/posters/maya-ko-sansaar.jpg", "dop": "Bikesh Magar", "e": "Bikesh Magar & Aakash Poudel", "credits": [{"r": "Art Direction", "n": "Ongdi Moktan"}, {"r":