INSERT INTO public.works (title, artist, director, year, category, youtube_id, synopsis, quote, quote_by, dop, editor, producer, production_design, colourist, bts_youtube_id, keyart_url, poster_url, credits, notes, is_published, sort_order)
VALUES ('Maya Ma', 'Purna Rai & Dajubhaiharu', 'Abhi Sampang Rai', '2025', 'Music Video', '5yuuRveinFc', '"In love" — Purna Rai''s unmistakable voice carrying a song about being fully, helplessly inside a feeling, with visuals to match its warmth.', '', '', '', '', '', '', '', '', 'assets/img/posters/maya-ma.jpg', '', '[]'::jsonb, ARRAY['Shristi Rai''s first executive-producer credit; Bikesh Magar covered camera, edit, VFX, and color across the entire post pipeline.']::text[], TRUE, 0);
INSERT INTO public.works (title, artist, director, year, category, youtube_id, synopsis, quote, quote_by, dop, editor, producer, production_design, colourist, bts_youtube_id, keyart_url, poster_url, credits, notes, is_published, sort_order)
VALUES ('Laijau Malai', 'Tribal Rain', 'Abhi Sampang Rai', '2025', 'Music Video', 'ntKzGQEDBXs', '"Take me away" — a yearning to be carried somewhere else entirely, given weight by Tribal Rain''s beloved catalogue and released on Valentine''s Day.', '', '', 'Bikesh Magar', 'Bikesh Magar', '', '', 'Bikesh Magar', '', '', '', '[{"r": "Art Direction", "n": "Shristi Rai"}, {"r": "Assistant Director", "n": "Saman Maharjan"}, {"r": "Make-Up & Stylist", "n": "Bomi Rai"}, {"r": "DIT", "n": "Purushottam Kandel"}, {"r": "Behind Credits", "n": "Santosh S. Thakuri"}]'::jsonb, ARRAY['A high-anticipation release for one of Nepal''s most cherished bands, premiered on Feb 14 with a full BTS companion film shot by Santosh Shah Thakuri.']::text[], TRUE, 1);
INSERT INTO public.works (title, artist, director, year, category, youtube_id, synopsis, quote, quote_by, dop, editor, producer, production_design, colourist, bts_youtube_id, keyart_url, poster_url, credits, notes, is_published, sort_order)
VALUES ('Ma Mare Pani', 'Swar', 'Abhi Sampang Rai', '2025', 'Music Video', 'lsqbpw67hSs', '"Even if I die" — devotion pushed to its absolute limit, a love professed beyond the boundary of life itself.', '', '', '', '', '', '', '', '', 'assets/img/posters/ma-mare-pani.jpg', '', '[]'::jsonb, ARRAY['A full-department production with Santosh Shah Thakuri managing post — the workflow template the studio now uses on most flagship videos.']::text[], TRUE, 2);
INSERT INTO public.works (title, artist, director, year, category, youtube_id, synopsis, quote, quote_by, dop, editor, producer, production_design, colourist, bts_youtube_id, keyart_url, poster_url, credits, notes, is_published, sort_order)
VALUES ('Sparsha Sangeet', 'Purna Rai & Dajubhaiharu', 'Abhi Sampang Rai', '2024', 'Music Video', 'K-w04FG6eyI', '"The music of touch" — a tactile, sensory love song rendered as a series of moments where sound and touch blur into one feeling.', '', '', 'Bikesh Magar', 'Robin Shrestha & Bikesh Magar & Ayush Suwal', '', 'Shristi Rai', 'Bikesh Magar', '', 'assets/img/posters/sparsha-sangeet.jpg', '', '[{"r": "Assistant Director", "n": "Saman Maharjan"}, {"r": "Cinematographer", "n": "Kiwa Khimdung Rai"}, {"r": "Art Direction", "n": "Shristi Rai"}, {"r": "Stylist", "n": "Shristi Rai"}, {"r": "Make-Up", "n": "Samasti Rai"}, {"r": "DIT", "n": "Purushottam Kandel"}]'::jsonb, ARRAY['One of the studio''s largest crews to date — a three-editor post team and production support from Kaagaz Productions, whose members (Arshu Shrestha, Ongdi Moktan, Rushal Shrestha) later became ChinoeTales regulars.']::text[], TRUE, 3);
INSERT INTO public.works (title, artist, director, year, category, youtube_id, synopsis, quote, quote_by, dop, editor, producer, production_design, colourist, bts_youtube_id, keyart_url, poster_url, credits, notes, is_published, sort_order)
