-- 6. Directors / Team Members
DELETE FROM public.directors;
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Abhi Sampang Rai', 'CEO / Director', 'assets/img/team/abhi.jpg', 'Cinematic Storytelling', 'Leads Chinoétales as both a company and a creative force, setting the studio''s vision while staying hands-on in the director''s chair. His signature combines bold visual aesthetics with deeply emotional storytelling, translating lyrical content into powerful visual metaphors.', '"I believe every song carries a visual story waiting to be discovered. Our job is not to create new stories, but to excavate the emotional truth already embedded in the music."', '["<b>Sparsha Sangeet</b> · Purna Rai & Dajubhaiharu", "<b>Ma Mare Pani</b> · Swar", "<b>Soltini</b> · Ekdev Limbu", "<b>Nindra Ma</b> · The Solace", "<b>Maya Ko Aago</b> · Rockheads"]'::jsonb, 0);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Bikesh Magar', 'CTO / DOP', 'assets/img/team/bikesh.jpg', 'Light & Composition', 'The technical backbone of Chinoétales'' image-making, leading the camera department while shaping the studio''s broader technical direction and equipment strategy. A cinematographer with a sharp eye for light and composition.', '"Technical excellence is the foundation upon which artistic vision stands. Every decision, from camera movement to colour temperature, serves the story."', '["<b>Ma Mare Pani</b> · Swar", "<b>Like Jennie</b> · Cover Project", "Lead DOP across commercials & music videos"]'::jsonb, 1);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Shristi Rai', 'CFO / Production Designer', 'assets/img/team/shristi.jpg', 'World-Building', 'Holds the financial backbone of Chinoétales together while shaping the visual world of every set she designs, blending a producer''s discipline with a designer''s eye for emotional authenticity and cultural sensitivity.', '"The most powerful stories are the ones that feel inevitable, where every visual choice seems like the only possible choice. That''s when art happens."', '["<b>Jhim Jhimaune Aankha</b> · Ekdev Limbu", "<b>Hey Sailaa</b> · Abhaya & The Steam Engines", "Production design across flagship projects"]'::jsonb, 2);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Aadi Pahari', 'Operational Manager', 'assets/img/team/aadi.jpg', 'Flawless Execution', 'Keeps Chinoétales running, the person who turns a creative brief into a schedule, a schedule into a shoot day, and a shoot day into a delivered project. Ground-level experience across productions of every scale means nothing falls through the cracks.', '"Great productions aren''t built on great ideas alone, they''re built on flawless execution. My role is making sure the team can focus on the work, not the logistics."', '[]'::jsonb, 3);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Santosh S. Thakuri', 'Creative Head', 'assets/img/team/santosh.jpg', 'Contemporary Energy', 'Brings fresh, contemporary energy to Chinoétales'' creative direction, shaping the studio''s evolving visual language, pushing projects toward dynamic, digital-age storytelling while staying rooted in cultural authenticity.', '"Every generation has its own visual language. My goal is to help our stories find expressions that feel true to this moment, honest, dynamic, and authentic."', '["Contemporary music video & commercial projects", "Ongoing creative direction across the pipeline"]'::jsonb, 4);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Devarshi.S', 'Creative Director', 'assets/img/team/devarshi.jpg', 'Visual Precision', 'Shapes the creative backbone of every production, translating raw concepts into a coherent visual and narrative direction, with meticulous composition, complex technical problem-solving, and an unwavering commitment to artistic integrity.', '"Technology should become invisible so the story can become everything. That''s the standard every creative decision has to meet."', '["<b>Ma Mare Pani</b> · Swar", "<b>Makhamali</b> · The Hulaki", "<b>Mandainani Mana</b> · Ekdev Limbu"]'::jsonb, 5);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Kiwa Khimdung Rai', 'Cinematographer', 'assets/img/team/kiwa.jpg', 'Motion & Frame', 'Brings a sharp visual instinct to every frame he shoots, serving the story through light, movement, and composition rather than spectacle for its own sake, across music videos, commercials, and documentary-style projects.', '"A shot only works if it disappears into the story. My job is to make every frame feel like it couldn''t have been captured any other way."', '[]'::jsonb, 6);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Samasti Rai', 'Art Director', 'assets/img/team/samasti.jpg', 'Production Design', 'Builds the visual world every Chinoétales project lives in, from set dressing to props to the overall aesthetic language of a production. Art direction is never an afterthought; it''s baked into the story from day one.', '"Great production design should never call attention to itself, it should just feel like the only world this story could exist in."', '["<b>Jhim Jhimaune Aankha</b> · Ekdev Limbu", "Art direction across music video & commercial projects"]'::jsonb, 7);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Ongdi Moktan', 'Art Director', 'assets/img/team/ongdi.jpg', 'Detail & Craft', 'Supports the art department across every stage of production, from prep and sourcing through on-set execution. An eye for detail that keeps the art department running smoothly under pressure.', '"The details nobody notices are usually the ones holding the whole shot together."', '[]'::jsonb, 8);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Dipika Rai', 'Content Manager', 'assets/img/team/dipika.jpg', 'Story & Reach', 'Manages how Chinoétales'' work reaches the world, coordinating content across platforms, timelines, and campaigns, from behind-the-scenes documentation to full release strategy for finished projects.', '"A great film still needs the right story told about how it reaches people. That''s the part of the job I care about most."', '[]'::jsonb, 9);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Arbind', 'DIT', 'assets/img/team/arbind.jpg', 'Data Integrity', 'Responsible for the integrity of Chinoétales'' footage from the moment it''s captured to the moment it reaches the edit suite, data management, on-set backups, and first-pass technical quality checks.', '"Nobody notices the DIT until something goes wrong. My job is making sure that never happens."', '[]'::jsonb, 10);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Nichal Gurung', 'Editor', 'assets/img/team/nischal.jpg', 'Rhythm & Pacing', 'Shapes the final rhythm of Chinoétales'' projects in the edit suite. With an innate sense of pacing and music-visual synchronisation, his editing is where performance, cinematography, and story finally come together.', '"Editing is where the story is truly told. When the cuts disappear, that''s when the audience stops watching and starts feeling."', '[]'::jsonb, 11);
INSERT INTO public.directors (name, role, photo_url, style, about, statement, works, sort_order)
VALUES ('Bomi Rai', 'Stylist', 'assets/img/team/bomi.jpg', 'Character & Look', 'Shapes how every artist and cast member looks on screen, wardrobe, styling, and the visual identity that has to hold up under studio lights and outdoor locations alike, always built for both camera and story.', '"Styling isn''t decoration, it''s characterisation. What someone wears has to tell you who they are before they say a single word."', '[]'::jsonb, 12);

