-- 8. FAQs
DELETE FROM public.faqs;
INSERT INTO public.faqs (question, answer, sort_order)
VALUES ('What does Chinoétales Productions do?', 'We are a story-driven film studio based in Kathmandu. We direct, shoot, and edit music videos, commercials, documentaries and visual narratives — from the first treatment through to the final grade.', 0);
INSERT INTO public.faqs (question, answer, sort_order)
VALUES ('How many people are on the team?', 'Thirteen. Direction, cinematography, production design, art direction, editing, styling and the operations that hold it all together are all in-house, and we work with a regular circle of collaborators beyond that.', 1);
INSERT INTO public.faqs (question, answer, sort_order)
VALUES ('How many films have you made?', 'Over 100 music videos released since 2021, for more than 50 artists and bands.', 2);
INSERT INTO public.faqs (question, answer, sort_order)
VALUES ('Do you work outside Kathmandu?', 'Yes. We are based in Kathmandu and available for projects anywhere — shoots have taken us across Nepal, and we take on international work.', 3);
INSERT INTO public.faqs (question, answer, sort_order)
VALUES ('What does a project usually involve?', 'Most begin with a conversation about the song and what it should feel like. From there we build the treatment, assemble the crew, shoot, and deliver the finished film — including the behind-the-scenes cut where the project calls for one.', 4);
INSERT INTO public.faqs (question, answer, sort_order)
VALUES ('How do I start a project with you?', 'Send us the track and a note about what you have in mind through the contact page. Tell us your timeline and any references, and we will come back to you — we typically respond within 48 hours.', 5);

-- 9. Services
DELETE FROM public.services;
INSERT INTO public.services (title, description, tags, sort_order) VALUES
('Music Videos', 'End-to-end creative direction, cinematography, and post-production for recording artists and record labels.', ARRAY['Direction', 'Cinematography', 'Post-Production']::text[], 0),
('Commercials & Brand Films', 'High-impact narrative and commercial filmmaking tailored for brands seeking distinctive visual identity.', ARRAY['Concept Development', 'Production', 'VFX']::text[], 1),
('Post-Production & VFX', 'Complete in-house editing, colour grading, visual effects, and digital delivery pipelines.', ARRAY['Editing', 'Colour Grading', 'VFX', 'Sound Design']::text[], 2),
('Creative Consultation', 'Treatment writing, visual world-building, lookbook development, and pre-production packaging.', ARRAY['Treatments', 'World-Building', 'Creative Direction']::text[], 3);
